import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Gestión de indexación","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/index-drives.md","filePath":"es-ES/user-guide/settings/index-drives.md","lastUpdated":1787586465000}'),n={name:"es-ES/user-guide/settings/index-drives.md"};function r(t,e,d,l,c,u){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="gestion-de-indexacion" tabindex="-1">Gestión de indexación <a class="header-anchor" href="#gestion-de-indexacion" aria-label="Permalink to &quot;Gestión de indexación&quot;">​</a></h1><p>La página de Indexación controla el alcance, la frecuencia de actualización y las reglas de exclusión para discos duros locales, recursos de red, distribuciones WSL y carpetas personalizadas. Contiene cinco pestañas: <strong>Unidades locales</strong>, <strong>Unidades de red</strong>, <strong>WSL</strong> (visible solo si se detectan distribuciones), <strong>Carpetas</strong> y <strong>Reglas de exclusión</strong>.</p><h2 id="_1-unidades-locales" tabindex="-1">1. Unidades locales <a class="header-anchor" href="#_1-unidades-locales" aria-label="Permalink to &quot;1. Unidades locales&quot;">​</a></h2><ul><li><strong>Tarjeta de estado superior</strong>: Muestra el total de unidades físicas y elementos indexados, con un botón global de <strong>Reconstruir índice</strong>.</li><li><strong>Filas de unidades</strong>: <ul><li><strong>Casilla de activación</strong>: Activa o desactiva la indexación para cada partición individual.</li><li><strong>Sistema de archivos y estado</strong>: Muestra el tipo de sistema de archivos (NTFS, ReFS, FAT32, exFAT), estado y recuento de elementos.</li><li><strong>Acciones por unidad</strong>: Botones independientes de <strong>Reconstruir</strong> y <strong>Eliminar</strong>; muestra un botón dinámico de <strong>Detener</strong> durante el escaneo.</li></ul></li><li><strong>Seguimiento en tiempo real</strong>: Los volúmenes NTFS / ReFS se sincronizan leyendo el diario de cambios USN de Windows; los volúmenes FAT32 / exFAT monitorizan eventos del sistema de archivos.</li><li><strong>Reconstrucción sin interrupciones</strong>: Durante la reconstrucción de una unidad, el índice existente sigue respondiendo a las consultas hasta que el nuevo esté listo, realizándose un intercambio instantáneo. Si se interrumpe, se reanuda desde el último punto en el siguiente inicio.</li></ul><h2 id="_2-unidades-de-red" tabindex="-1">2. Unidades de red <a class="header-anchor" href="#_2-unidades-de-red" aria-label="Permalink to &quot;2. Unidades de red&quot;">​</a></h2><ul><li><strong>Soporte de almacenamiento en red</strong>: Lista todas las unidades de red asignadas en Windows (SMB / NAS).</li><li><strong>Modo de actualización</strong>: Al carecer de diarios USN locales, se puede programar su sondeo: <ul><li><strong>Manual</strong> — Se actualiza solo al pulsar &quot;Reconstruir índice&quot;.</li><li><strong>Cada 15 minutos</strong> — Recomendado para recursos colaborativos activos.</li><li><strong>Cada hora</strong> — Escaneo periódico equilibrado.</li><li><strong>Diario</strong> — Ideal para almacenamiento estático o de archivo.</li></ul></li><li><strong>Protección contra bucles de enlaces simbólicos</strong>: Algoritmos internos de detección de bucles evitan atascos provocados por enlaces simbólicos recursivos en carpetas NAS.</li></ul><h2 id="_3-wsl-subsistema-de-windows-para-linux" tabindex="-1">3. WSL (Subsistema de Windows para Linux) <a class="header-anchor" href="#_3-wsl-subsistema-de-windows-para-linux" aria-label="Permalink to &quot;3. WSL (Subsistema de Windows para Linux)&quot;">​</a></h2><p>Aparece automáticamente si se detecta al menos una distribución WSL instalada:</p><ul><li><strong>Detección automática</strong>: Reconoce Ubuntu, Debian, Arch y otras distribuciones.</li><li><strong>Estado y programación</strong>: Misma gestión y modos de actualización (Manual / 15 min / Cada hora / Diario).</li><li><strong>Consultas con latencia cero</strong>: Busca directamente en el índice en memoria sin despertar ni ralentizar el subsistema Linux.</li></ul><h2 id="_4-carpetas" tabindex="-1">4. Carpetas <a class="header-anchor" href="#_4-carpetas" aria-label="Permalink to &quot;4. Carpetas&quot;">​</a></h2><p>Útil cuando se desea indexar carpetas de trabajo específicas en lugar de volúmenes completos:</p><ul><li><strong>Adición múltiple</strong>: Pulsa <strong>Añadir carpeta</strong> para abrir un selector que permite selecciones múltiples con <code>Ctrl</code> o <code>Shift</code>.</li><li><strong>Rutas UNC</strong>: Admite rutas compartidas de red (p. ej. <code>\\\\server\\share\\projects</code>).</li><li><strong>Programación independiente</strong>: Cada carpeta dispone de su propio interruptor, contador y modo de actualización.</li></ul><h2 id="_5-reglas-de-exclusion" tabindex="-1">5. Reglas de exclusión <a class="header-anchor" href="#_5-reglas-de-exclusion" aria-label="Permalink to &quot;5. Reglas de exclusión&quot;">​</a></h2><p>Se aplican globalmente a discos locales, red y carpetas, organizadas en tres subpestañas:</p><h3 id="exclusion-de-rutas" tabindex="-1">Exclusión de rutas <a class="header-anchor" href="#exclusion-de-rutas" aria-label="Permalink to &quot;Exclusión de rutas&quot;">​</a></h3><ul><li><strong>Coincidencia por prefijo</strong>: Excluye rutas absolutas (<code>D:\\Cache</code>) o variables de entorno (<code>%ProgramData%</code>, <code>%APPDATA%</code>).</li></ul><h3 id="reglas-glob" tabindex="-1">Reglas Glob <a class="header-anchor" href="#reglas-glob" aria-label="Permalink to &quot;Reglas Glob&quot;">​</a></h3><ul><li><strong>Sintaxis</strong>: <ul><li><code>*</code>: Coincide con caracteres dentro de un mismo nivel (p. ej. <code>*.tmp</code>, <code>*.log</code>).</li><li><code>**</code>: Coincidencia recursiva entre subdirectorios (p. ej. <code>**/node_modules/**</code>, <code>**/bin/**</code>, <code>**/obj/**</code>).</li></ul></li></ul><h3 id="reglas-de-expresiones-regulares" tabindex="-1">Reglas de expresiones regulares <a class="header-anchor" href="#reglas-de-expresiones-regulares" aria-label="Permalink to &quot;Reglas de expresiones regulares&quot;">​</a></h3><ul><li><strong>Filtrado avanzado</strong>: Coincidencia mediante regex contra rutas y nombres de archivo (p. ej. <code>^\\.</code> para archivos ocultos, <code>~\\$</code> para temporales de Office).</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Las exclusiones admiten <strong>adición individual</strong> e <strong>importación/exportación por lotes</strong>: pulsa <strong>Generar desde lista</strong> para exportar las reglas a texto, edítalas y pulsa <strong>Aplicar a la lista</strong> para actualizarlas en bloque.</p></div>',21)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
